// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"cmp"
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"slices"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// entry is a queued job with its place in enqueue order.
type entry struct {
	seq uint64
	job Job
}

// running is a job that a worker is executing.
type running struct {
	cancel   context.CancelFunc
	canceled bool // Shutdown canceled its context
}

// Runner runs jobs on its workers.
type Runner struct {
	queue   chan entry
	workers int
	log     *slog.Logger
	wg      sync.WaitGroup // the workers

	mu          sync.Mutex
	seq         uint64
	stopping    bool
	waiting     map[uint64]Job      // enqueued and not started
	active      map[uint64]*running // started and not finished
	interrupted []entry             // canceled by Shutdown and returned an error
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	return &Runner{
		queue:   make(chan entry, queueSize),
		workers: workers,
		log:     log,
		waiting: map[uint64]Job{},
		active:  map[uint64]*running{},
	}
}

// Start starts the workers. It does nothing once Shutdown has been called.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for e := range r.queue {
		r.mu.Lock()
		if r.stopping {
			// Shutdown has begun, so the job stays in waiting and Pending reports it.
			r.mu.Unlock()
			continue
		}
		delete(r.waiting, e.seq)
		ctx, cancel := context.WithCancel(context.Background())
		run := &running{cancel: cancel}
		r.active[e.seq] = run
		r.mu.Unlock()

		err := r.call(ctx, e.job)
		cancel()

		r.mu.Lock()
		delete(r.active, e.seq)
		if run.canceled && err != nil {
			r.interrupted = append(r.interrupted, e)
		}
		r.mu.Unlock()
		if err != nil {
			r.log.Error("job failed", "job", e.job.Name, "err", err)
		}
	}
}

// call runs j. A panic is logged and recovered, so the worker moves on to the next job.
func (r *Runner) call(ctx context.Context, j Job) (err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p, "stack", string(debug.Stack()))
		}
	}()
	return j.Run(ctx)
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping {
		return ErrStopped
	}
	e := entry{seq: r.seq + 1, job: j}
	select {
	case r.queue <- e:
		r.seq = e.seq
		r.waiting[e.seq] = j
		return nil
	default:
		return ErrQueueFull
	}
}

// Shutdown stops the runner. From now on Enqueue returns ErrStopped, and jobs that have not started are not
// started. It waits for running jobs to finish. If ctx ends first, it cancels the context of every running job,
// waits for them to return, and returns ctx.Err(). A call after the first returns nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.stopping {
		r.mu.Unlock()
		return nil
	}
	r.stopping = true
	close(r.queue) // Enqueue checks stopping under mu, so it cannot send on the closed queue
	r.mu.Unlock()

	finished := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(finished)
	}()

	select {
	case <-finished:
		return nil
	case <-ctx.Done():
	}
	r.mu.Lock()
	for _, run := range r.active {
		run.canceled = true
		run.cancel()
	}
	r.mu.Unlock()
	<-finished
	return ctx.Err()
}

// Stop shuts the runner down like Shutdown, waiting at most 30 seconds for running jobs.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued jobs
// that have not started. After Shutdown they are the jobs that were never started, followed by the jobs whose
// context Shutdown canceled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	seqs := make([]uint64, 0, len(r.waiting))
	for seq := range r.waiting {
		seqs = append(seqs, seq)
	}
	slices.Sort(seqs)
	out := make([]Job, 0, len(seqs)+len(r.interrupted))
	for _, seq := range seqs {
		out = append(out, r.waiting[seq])
	}
	interrupted := slices.Clone(r.interrupted)
	slices.SortFunc(interrupted, func(a, b entry) int { return cmp.Compare(a.seq, b.seq) })
	for _, e := range interrupted {
		out = append(out, e.job)
	}
	return out
}
