	"testing"
	"time"
)

func TestRunnerRunsJobs(t *testing.T) {
	r := NewRunner(3, 10, nil)
	r.Start()
	var mu sync.Mutex
	done := map[string]bool{}
	var wg sync.WaitGroup
	for _, name := range []string{"a", "b", "c", "d", "e"} {
		wg.Add(1)
		if err := r.Enqueue(Job{Name: name, Run: func(ctx context.Context) error {
			defer wg.Done()
			mu.Lock()
			done[name] = true
			mu.Unlock()
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	finished := make(chan struct{})
	go func() { wg.Wait(); close(finished) }()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
		t.Fatal("jobs did not run")
	}
	if len(done) != 5 {
		t.Fatalf("done = %v", done)
	}
}

func TestEnqueueWhenFull(t *testing.T) {
	r := NewRunner(1, 1, nil) // not started: nothing takes jobs off the queue
	job := Job{Name: "x", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("err = %v, want ErrQueueFull", err)
	}
}

func TestPendingBeforeShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started
	for _, name := range []string{"a", "b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if got := jobNames(r.Pending()); !slices.Equal(got, []string{"a", "b", "c"}) {
		t.Fatalf("pending = %v", got)
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got := jobNames(r.Pending()); !slices.Equal(got, []string{"a", "b", "c"}) {
		t.Fatalf("pending after shutdown = %v, want the jobs that never started", got)
	}
}

func TestEnqueueAfterShutdownReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", jobNames(got))
	}
}

func TestShutdownWaitsForRunningJob(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	var finished atomic.Bool
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		close(started)
		time.Sleep(50 * time.Millisecond)
		finished.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	waitFor(t, started)
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if !finished.Load() {
		t.Fatal("Shutdown returned before the running job finished")
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", jobNames(got))
	}
}

func TestShutdownCancelsRunningJobAndKeepsUnstartedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	if err := r.Enqueue(Job{Name: "blocker", Run: func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		return ctx.Err()
	}}); err != nil {
		t.Fatal(err)
	}
	waitFor(t, started)
	var ran atomic.Int32
	for _, name := range []string{"second", "third"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { ran.Add(1); return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	if n := ran.Load(); n != 0 {
		t.Fatalf("%d unstarted jobs ran", n)
	}
	// The unstarted jobs come first, then the canceled job that returned an error.
	if got := jobNames(r.Pending()); !slices.Equal(got, []string{"second", "third", "blocker"}) {
		t.Fatalf("pending = %v", got)
	}
}

