func TestSecondShutdownWaitsForFirst(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	var finished atomic.Bool
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		close(started)
		<-release
		finished.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	waitFor(t, started)

	firstDone := make(chan error, 1)
	go func() { firstDone <- r.Shutdown(context.Background()) }()

	secondDone := make(chan error, 1)
	go func() {
		// Wait until the first call has stopped the runner, so this call is the repeat.
		for {
			if err := r.Enqueue(Job{Name: "late", Run: func(context.Context) error { return nil }}); errors.Is(err, ErrStopped) {
				break
			}
			time.Sleep(time.Millisecond)
		}
		secondDone <- r.Shutdown(context.Background())
	}()

	select {
	case err := <-secondDone:
		t.Fatalf("second Shutdown returned %v while the running job was still going", err)
	case <-time.After(50 * time.Millisecond):
	}
	close(release)
	if err := <-secondDone; err != nil {
		t.Fatalf("second Shutdown = %v, want nil", err)
	}
	if err := <-firstDone; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}
	if !finished.Load() {
		t.Fatal("second Shutdown returned before the running job finished")
	}
}

